    // Within a batch: base 1000ms * 0.25 = 250ms.
    const inBatch = wave({ waveNumber: 1, enemiesSpawned: 0, lastSpawnTime: 0 });
    game.activeWaves = [inBatch];
    game.update(300);
    expect(game.spawnEnemy).toHaveBeenCalledWith(false, inBatch);

