    const inBatch = wave({ waveNumber: 4, enemiesSpawned: 0, lastSpawnTime: 0 });
    game.activeWaves = [inBatch];
    game.update(150);
    expect(game.spawnEnemy).toHaveBeenCalledWith(false, inBatch);

