    game.activeWaves = [betweenBatches];
    game.update(2500);
    expect(game.spawnEnemy).not.toHaveBeenCalled();
    game.update(3100);
    expect(game.spawnEnemy).toHaveBeenCalledTimes(1);
    expect(game.spawnEnemy).toHaveBeenCalledWith(false, betweenBatches);
  });

