    game.activeWaves = [wave({ waveNumber: 6, completed: true, enemiesSpawned: 110 })];

    game.update(10000);

    expect(game.waveInProgress).toBe(false);
    expect(game.victory).toHaveBeenCalledTimes(1);
    expect(game.renderer.render).toHaveBeenCalledWith(game);
  });

  test('clears wave-in-progress without victory when earlier waves finish', () => {
    const game = createGame();
    game.waveInProgress = true;
    game.currentWave = 2;
    game.maxWaves = 6;
    game.lastEnemySpawnTime = 9000;
    game.activeWaves = [wave({ waveNumber: 2, completed: true, enemiesSpawned: 30 })];

    game.update(10000);

    expect(game.waveInProgress).toBe(false);
    expect(game.victory).not.toHaveBeenCalled();
  });

  test('keeps the wave in progress while an enemy in an active wave is still alive', () => {
    const game = createGame();
    game.waveInProgress = true;
    game.currentWave = 1;
    game.lastEnemySpawnTime = 9000;
    const activeWave = wave({ waveNumber: 1, enemiesSpawned: 15, enemiesAlive: 1 });
