    game.update(10000);

    expect(game.waveInProgress).toBe(true);
    expect(game.victory).not.toHaveBeenCalled();
    expect(game.spawnEnemy).not.toHaveBeenCalled();
  });

  test('does not clear the in-progress flag based on counts alone when waves are not marked complete', () => {
    const game = createGame();
    game.waveInProgress = true;
    game.currentWave = 1;
    game.lastEnemySpawnTime = 9000;
    game.activeWaves = [wave({ waveNumber: 1, enemiesSpawned: 15, enemiesAlive: 0, completed: false })];

    game.update(10000);

    expect(game.waveInProgress).toBe(true);
    expect(game.victory).not.toHaveBeenCalled();
  });
});

