            const getRandomElement = jest.fn(() => 'fire');
            const game = makeGame({ currentWave: 1, getRandomElement });
            mockRandom(0.4); // only wave 6 early-spawn positioning needs it

            const enemy = game.spawnEnemy(true, waveInfo);

            expect(enemy.type).toBe('golem');
            expect(enemy.elementType).toBe('fire');
            expect(enemy.maxHealth).toBe(expectedHealth);
            expect(enemy.health).toBe(expectedHealth);
            expect(enemy.baseSpeed).toBeCloseTo(2.1);
            expect(enemy.reward).toBe(expectedReward);
            expect(enemy.enemyInstance.scale).toBeCloseTo(expectedScale);
            expect(enemy.waveNumber).toBe(waveNumber);
            expect(waveInfo.enemiesSpawned).toBe(spawned + 1);
            expect(waveInfo.enemiesAlive).toBe(1);
        }
    );

    test('does not fail or rescale when the instance manager is unavailable', () => {
        const game = makeGame({
            currentWave: 1,
            renderer: { enemyInstanceManager: null }
        });
        mockRandom(0.5);

        const enemy = game.spawnEnemy(true, {
            waveNumber: 4,
            enemiesSpawned: 0,
            enemiesAlive: 0
        });

        expect(enemy.enemyInstance.scale).toBe(1);
        expect(enemy.maxHealth).toBe(900);
    });
});

// ---------------------------------------------------------------------------
// Stat variation, rewards, and bookkeeping
// ---------------------------------------------------------------------------
describe('Game.spawnEnemy stat variation and rewards', () => {
    test('applies deterministic random health and speed variation to non-bosses', () => {
        const game = makeGame({
            currentWave: 1,
            difficultySettings: {
                ...DEFAULT_DIFFICULTY,
                randomFactorMultiplier: 0.6
            }
        });
        mockRandom(0, 0, 0.5); // entry, health variation, speed variation

        const enemy = game.spawnEnemy();

        expect(enemy.maxHealth).toBeCloseTo(80);
        expect(enemy.health).toBeCloseTo(80);
        expect(enemy.baseSpeed).toBeCloseTo(3.3);
    });

    test('does not vary stats when randomFactorMultiplier is zero', () => {
        const game = makeGame({
            currentWave: 1,
            difficultySettings: {
                ...DEFAULT_DIFFICULTY,
                randomFactorMultiplier: 0
            }
        });
        mockRandom(0.5);

        const enemy = game.spawnEnemy();

        expect(enemy.maxHealth).toBe(100);
        expect(enemy.baseSpeed).toBe(3);
    });

    test('applies the wave and difficulty gold multipliers to rewards', () => {
        const game = makeGame({
            currentWave: 3,
            difficultySettings: {
                ...DEFAULT_DIFFICULTY,
                goldMultiplier: 1.5
            }
        });
        mockRandom(0.5, 0.5); // elephant, no element

        const enemy = game.spawnEnemy();

        expect(enemy.type).toBe('elephant');
        expect(enemy.reward).toBe(21); // ceil(10 * 1.4 * 1.5)
        expect(enemy.waveNumber).toBe(3);
        expect(game.enemiesSpawned).toBe(1);
    });

    test('uses waveInfo for wave association and counters without touching game counters', () => {
        const game = makeGame({ currentWave: 1, enemiesSpawned: 7 });
        const waveInfo = { waveNumber: 2, enemiesSpawned: 4, enemiesAlive: 2 };
        mockRandom(0.5);

        const enemy = game.spawnEnemy(false, waveInfo);

        expect(enemy.waveNumber).toBe(2);
        expect(enemy.type).toBe('simple');
        expect(waveInfo.enemiesSpawned).toBe(5);
        expect(waveInfo.enemiesAlive).toBe(3);
        expect(game.enemiesSpawned).toBe(7);
        expect(game.enemies).toEqual([enemy]);
    });
});

// ---------------------------------------------------------------------------
// Late-wave spawn entry patterns
// ---------------------------------------------------------------------------
describe('Game.spawnEnemy late-wave entry-point patterns', () => {
    const baseMap = () => createMap({ width: 10, height: 8 });

    test.each([
        [0, [], 2], // left quarter
        [1, [], 7], // right three-quarter
        [2, [0.5, 0.4], 1], // edge, left edge
        [3, [0.5, 0.6], 9], // edge, right edge
        [4, [0.7, 0.5], 5] // center-ish
    ])(
        'wave 4 spawned index %i chooses entry x=%i',
        (spawned, randomValues, expectedX) => {
            const map = baseMap();
            const game = makeGame({ currentWave: 1, map });
            const waveInfo = { waveNumber: 4, enemiesSpawned: spawned, enemiesAlive: 0 };
            mockRandom(...randomValues);

            game.spawnEnemy(false, waveInfo);

            expect(map.gridToWorld).toHaveBeenCalledWith(expectedX, 0);
        }
    );

    test.each([
        [0, 2], // first group, left
        [4, 8], // second group, right
        [8, 5] // third group, center
    ])('wave 5 starts group at spawned index %i with entry x=%i', (spawned, expectedX) => {
        const map = baseMap();
        const game = makeGame({ currentWave: 1, map });
        const waveInfo = { waveNumber: 5, enemiesSpawned: spawned, enemiesAlive: 0 };
        mockRandom(0.5);

        game.spawnEnemy(false, waveInfo);

        expect(map.gridToWorld).toHaveBeenCalledWith(expectedX, 0);
        expect(waveInfo.currentSpawnPoint).toEqual({ x: expectedX, z: 0 });
    });

    test('wave 5 reuses the current group spawn point for members after the first', () => {
        const map = baseMap();
        const game = makeGame({ currentWave: 1, map });
        const waveInfo = {
            waveNumber: 5,
            enemiesSpawned: 1,
            enemiesAlive: 0,
            currentSpawnPoint: { x: 3, z: 0 }
        };
        const random = mockRandom(0.5);

        game.spawnEnemy(false, waveInfo);

        expect(random).not.toHaveBeenCalled();
        expect(map.gridToWorld).toHaveBeenCalledWith(3, 0);
        expect(waveInfo.currentSpawnPoint).toEqual({ x: 3, z: 0 });
    });

    test.each([
        [0, [0.4], 1], // early wave, left edge
        [10, [0.6], 8], // early wave, right edge
        [30, [0.1, 0.5], 1], // mid wave, left third
        [40, [0.4, 0.5], 8], // mid wave, right third
        [50, [0.6, 0.5], 4], // mid wave, center
        [70, [0.4], 4] // late wave, random center
    ])('wave 6 spawned index %i chooses entry x=%i', (spawned, randomValues, expectedX) => {
        const map = baseMap();
        const game = makeGame({ currentWave: 1, map });
        const waveInfo = { waveNumber: 6, enemiesSpawned: spawned, enemiesAlive: 0 };
        mockRandom(...randomValues);

        game.spawnEnemy(false, waveInfo);

        expect(map.gridToWorld).toHaveBeenCalledWith(expectedX, 0);
    });

    test('wave 6 reuses the current group spawn point within an adaptive group', () => {
        const map = baseMap();
        const game = makeGame({ currentWave: 1, map });
        const waveInfo = {
            waveNumber: 6,
            enemiesSpawned: 11, // ratio 0.11 => adaptive group size 2, second member
            enemiesAlive: 0,
            currentSpawnPoint: { x: 6, z: 0 }
        };
        const random = mockRandom(0.5);

        game.spawnEnemy(false, waveInfo);

        expect(random).not.toHaveBeenCalled();
        expect(map.gridToWorld).toHaveBeenCalledWith(6, 0);
    });
});

// ---------------------------------------------------------------------------
// Visual-instance fallback
// ---------------------------------------------------------------------------
describe('Game.spawnEnemy visual instance fallback', () => {
    test('recreates a missing visual instance and logs a warning', () => {
        mockEnemyState.createInstance = false;
        const replacement = {
            scale: 1,
            baseType: 'replacement',
            elementType: 'neutral',
            instanceIndex: 0
        };
        const createEnemy = jest.fn(() => replacement);
        const game = makeGame({ currentWave: 1, renderer: { createEnemy } });
        const warn = jest.spyOn(console, 'warn').mockImplementation(() => {});
        mockRandom(0.5);

        const enemy = game.spawnEnemy();

        expect(createEnemy).toHaveBeenCalledWith(enemy);
        expect(enemy.enemyInstance).toBe(replacement);
        expect(warn).toHaveBeenCalledWith(
            expect.stringContaining('missing visual instance')
        );
    });

    test('logs an error when visual recreation also fails', () => {
        mockEnemyState.createInstance = false;
        const createEnemy = jest.fn(() => null);
        const game = makeGame({ currentWave: 1, renderer: { createEnemy } });
        jest.spyOn(console, 'warn').mockImplementation(() => {});
        const error = jest.spyOn(console, 'error').mockImplementation(() => {});
        mockRandom(0.5);

        const enemy = game.spawnEnemy();

        expect(enemy.enemyInstance).toBeUndefined();
        expect(error).toHaveBeenCalledWith(
            expect.stringContaining('Failed to create enemy visual representation')
        );
    });
});
