import { jest } from '@jest/globals';

// ---------------------------------------------------------------------------
// Controlled collaborators
// ---------------------------------------------------------------------------
// Enemy is replaced with a minimal observable double so these tests focus on
// Game.spawnEnemy's decisions rather than Enemy's own stat/pathfinding code.
const mockEnemyState = {
    instances: [],
    createInstance: true
};

jest.unstable_mockModule('../../src/entities/enemy.js', () => {
    class Enemy {
        constructor(game, type, startPosition, elementType) {
            this.game = game;
            this.type = type;
            this.position = startPosition;
            this.elementType = elementType;

            // Base values that spawnEnemy is allowed to modify.
            this.maxHealth = 100;
            this.health = 100;
            this.baseSpeed = 3;
            this.reward = 10;
            this.waveNumber = 1;

            if (mockEnemyState.createInstance) {
                this.enemyInstance = {
                    scale: 1,
                    baseType: type,
                    elementType,
                    instanceIndex: 0
                };
            }

            mockEnemyState.instances.push(this);
        }
    }

    return { Enemy };
});

let Game;

beforeAll(async () => {
    ({ Game } = await import('../../src/game.js'));
});

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------
const DEFAULT_WAVE_SETTINGS = [
    { enemyCount: 15, goldMultiplier: 1.0 },
    { enemyCount: 30, goldMultiplier: 1.2 },
    { enemyCount: 50, goldMultiplier: 1.4 },
    { enemyCount: 70, goldMultiplier: 1.5 },
    { enemyCount: 90, goldMultiplier: 1.6 },
    { enemyCount: 100, goldMultiplier: 1.6 }
];

const DEFAULT_DIFFICULTY = {
    bossHealthMultiplier: 3.0,
    bossSpeedMultiplier: 0.7,
    lateStageBossBonus: 2.0,
    goldMultiplier: 1.0,
    randomFactorMultiplier: 0
};

function createMap({ width = 10, height = 8, topRow = null } = {}) {
    const row = topRow ? [...topRow] : Array(width).fill(1);
    const grid = Array.from({ length: height }, (_, z) =>
        z === 0 ? [...row] : Array(width).fill(1)
    );

    return {
        grid,
        gridWidth: width,
        gridHeight: height,
        gridToWorld: jest.fn((x, z) => ({
        [40, [0.4, 0.5], 8], // mid wave, right third
        [50, [0.6, 0.5], 5], // mid wave, center
        [70, [0.4], 4] // late wave, random center
    ])('wave 6 spawned index %i (randoms %j) chooses entry x=%i', (spawned, randomValues, expectedX) => {
        const map = baseMap();
        const game = makeGame({ currentWave: 1, map });
        const waveInfo = { waveNumber: 6, enemiesSpawned: spawned, enemiesAlive: 0 };
        mockRandom(...randomValues);

        game.spawnEnemy(false, waveInfo);

        expect(map.gridToWorld).toHaveBeenCalledWith(expectedX, 0);
    });

    test('wave 6 reuses the current group spawn point within an adaptive group', () => {
        const map = baseMap();
        const game = makeGame({ currentWave: 1, map });
        const waveInfo = {
            waveNumber: 6,
            enemiesSpawned: 11, // ratio 0.11 => adaptive group size 2, second member
            enemiesAlive: 0,
            currentSpawnPoint: { x: 6, z: 0 }
        };
        const random = mockRandom(0.5);

        game.spawnEnemy(false, waveInfo);

        expect(random).not.toHaveBeenCalled();
        expect(map.gridToWorld).toHaveBeenCalledWith(6, 0);
    });
});

// ---------------------------------------------------------------------------
// Visual-instance fallback
// ---------------------------------------------------------------------------
describe('Game.spawnEnemy visual instance fallback', () => {
    test('recreates a missing visual instance and logs a warning', () => {
        mockEnemyState.createInstance = false;
        const replacement = {
            scale: 1,
            baseType: 'replacement',
            elementType: 'neutral',
            instanceIndex: 0
        };
        const createEnemy = jest.fn(() => replacement);
        const game = makeGame({ currentWave: 1, renderer: { createEnemy } });
        const warn = jest.spyOn(console, 'warn').mockImplementation(() => {});
        jest.spyOn(console, 'log').mockImplementation(() => {});
        mockRandom(0.5);

        const enemy = game.spawnEnemy();

        expect(createEnemy).toHaveBeenCalledWith(enemy);
        expect(enemy.enemyInstance).toBe(replacement);
        expect(warn).toHaveBeenCalledWith(
            expect.stringContaining('missing visual instance')
        );
    });

    test('logs an error when visual recreation also fails', () => {
        mockEnemyState.createInstance = false;
        const createEnemy = jest.fn(() => null);
        const game = makeGame({ currentWave: 1, renderer: { createEnemy } });
        jest.spyOn(console, 'warn').mockImplementation(() => {});
        const error = jest.spyOn(console, 'error').mockImplementation(() => {});
        mockRandom(0.5);

        const enemy = game.spawnEnemy();

        expect(enemy.enemyInstance).toBeNull();
        expect(error).toHaveBeenCalledWith(
            expect.stringContaining('Failed to create enemy visual representation')
        );
    });
});
